#[path = "solution.rs"]
mod solution;

use std::collections::BTreeSet;
use solution::{advance, decode_flips, Cell};

fn set(values: &[Cell]) -> BTreeSet<Cell> {
    values.iter().copied().collect()
}

#[test]
fn decodes_all_directions_and_toggles_repeated_destinations() {
    let cells = decode_flips("r\nl\nur\nul\ndr\ndl\nr\n").expect("valid paths");
    assert_eq!(cells, set(&[(-1, 0), (1, -1), (0, -1), (0, 1), (-1, 1)]));
}

#[test]
fn scans_compound_paths_left_to_right() {
    let cells = decode_flips("ruruldrdl\nrrul\n").expect("valid compound paths");
    assert_eq!(cells, set(&[(0, 0), (2, -1)]));
}

#[test]
fn empty_and_blank_inputs_decode_to_empty_set() {
    assert!(decode_flips("").unwrap().is_empty());
    assert!(decode_flips("\n\n").unwrap().is_empty());
}

#[test]
fn any_invalid_or_incomplete_token_rejects_entire_decode() {
    for input in ["u", "d", "rx", "urq", "r\nvalid", "rr\ndl\nu"] {
        assert!(decode_flips(input).is_err(), "unexpected success for {input:?}");
    }
}

#[test]
fn zero_rounds_clones_without_mutating_input() {
    let cells = set(&[(0, 0), (1, 0)]);
    let original = cells.clone();
    let result = advance(&cells, 0);
    assert_eq!(result, cells);
    assert_eq!(cells, original);
}

#[test]
fn survival_birth_and_disappearance_follow_neighbor_counts() {
    let cells = set(&[(0, 0), (1, 0)]);
    let original = cells.clone();
    let next = advance(&cells, 1);
    assert_eq!(next, set(&[(0, 0), (1, 0), (1, -1), (0, 1)]));
    assert_eq!(cells, original);

    let isolated = set(&[(4, -3)]);
    assert!(advance(&isolated, 1).is_empty());
}

#[test]
fn multiple_rounds_are_equivalent_to_repeated_single_rounds() {
    let cells = set(&[(0, 0), (1, 0), (0, 1)]);
    let two_at_once = advance(&cells, 2);
    let one_then_one = advance(&advance(&cells, 1), 1);
    assert_eq!(two_at_once, one_then_one);
}

